<?php $page='calendar';$title='Calendar';require_once __DIR__.'/includes/functions.php';require_login();$uid=$_SESSION['user_id'];$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$first=strtotime($month.'-01');$days=(int)date('t',$first);$offset=(int)date('N',$first)-1;$q=$pdo->prepare('SELECT * FROM transactions WHERE user_id=? AND transaction_date BETWEEN ? AND ? ORDER BY transaction_date');$q->execute([$uid,$month.'-01',date('Y-m-t',$first)]);$events=[];foreach($q as $r)$events[(int)date('j',strtotime($r['transaction_date']))][]=$r;require 'includes/header.php';?>
<div class="page-head"><div><h1>Calendar</h1><p>View your income and expenses by date.</p></div><form method="get"><input type="month" name="month" value="<?=e($month)?>"><button class="btn">View</button></form></div><div class="card"><h3><?=e(date('F Y',$first))?></h3><div class="calendar"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $d):?><div><strong><?=e($d)?></strong></div><?php endforeach;for($i=0;$i<$offset;$i++):?><div class="day"></div><?php endfor;for($d=1;$d<=$days;$d++):?><div class="day"><strong><?=$d?></strong><?php foreach($events[$d]??[] as $ev):?><span class="event"><?=e(ucfirst($ev['type']))?>: <?=e($ev['description'])?> (<?=money($ev['amount'])?>)</span><?php endforeach;?></div><?php endfor;?></div></div><?php require 'includes/footer.php';?>
